(4085675, 584918, 81530, '<td valign="top">Great action shot. Exposure is great. The crop is a little awkward on the bottom left(his shoe) and middle right (right beside his rear end). I feel that if the crop was either wider to include all the information, or tighter to look more deliberate, that this shot would be even stronger.</td>', 'Great action shot. Exposure is great. The crop is a little awkward on the bottom left(his shoe) and middle right (right beside his rear end). I feel that if the crop was either wider to include all the information, or tighter to look more deliberate, that this shot would be even stronger.', '2007-09-12 21:14:56.000000', NULL, 1),
(4085676, 584310, 81530, '<td valign="top">Very nice find. It takes a while to understand what is happening here, and I think that is a good thing because it keeps the viewer interested.</td>', 'Very nice find. It takes a while to understand what is happening here, and I think that is a good thing because it keeps the viewer interested.', '2007-09-12 21:16:00.000000', NULL, 1),
(4085678, 584615, 81530, '<td valign="top">Very nice highlights on the spider and the web. I like the strong colors in the background. The focus on the spider and his web could be sharper.</td>', 'Very nice highlights on the spider and the web. I like the strong colors in the background. The focus on the spider and his web could be sharper.', '2007-09-12 21:16:32.000000', NULL, 1),
(4085680, 585793, 81530, '<td valign="top">Very nice idea. I like shots where objects emerge from the darkness. If I were to crop this photo, I would crop above the blue floor and red line so that the gym floor is coming out of the darkness but still have some mystery to it.</td>', 'Very nice idea. I like shots where objects emerge from the darkness. If I were to crop this photo, I would crop above the blue floor and red line so that the gym floor is coming out of the darkness but still have some mystery to it.', '2007-09-12 21:18:40.000000', NULL, 1),
(4085682, 585480, 81530, '<td valign="top">Very creative. Great idea. The lighting is very nice as well.</td>', 'Very creative. Great idea. The lighting is very nice as well.', '2007-09-12 21:19:17.000000', NULL, 1),
(4085684, 585218, 81530, '<td valign="top">Great sunset shot. Love the silhouette and the deep reds in the sky.</td>', 'Great sunset shot. Love the silhouette and the deep reds in the sky.', '2007-09-12 21:19:46.000000', NULL, 1),
(4085685, 584863, 81530, '<td valign="top">Good action shot. I like the contrast between the red clay and the blue wall.</td>', 'Good action shot. I like the contrast between the red clay and the blue wall.', '2007-09-12 21:20:17.000000', NULL, 1),
(4085686, 585816, 81530, '<td valign="top">Very simple image. I like the contrast between the straight lines of the door and windows compared to the scratches and chips that give the door character.</td>', 'Very simple image. I like the contrast between the straight lines of the door and windows compared to the scratches and chips that give the door character.', '2007-09-12 21:21:23.000000', NULL, 1),
(4085687, 585781, 81530, '<td valign="top">Very nice shot. Great focusing. Love the water droplet details on the web. Great use of the rule of thirds. Good shot!</td>', 'Very nice shot. Great focusing. Love the water droplet details on the web. Great use of the rule of thirds. Good shot!', '2007-09-12 21:22:02.000000', NULL, 1),
(4085691, 585696, 81530, '<td valign="top">This photo seems very personal. I like the overall feel with the tones, despite the fact there aren''t any bright whites. Great shot!</td>', 'This photo seems very personal. I like the overall feel with the tones, despite the fact there aren''t any bright whites. Great shot!', '2007-09-12 21:23:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4085692, 584138, 81530, '<td valign="top">I like the way you have lined up the reflection of the sun and the small island. Nice work.</td>', 'I like the way you have lined up the reflection of the sun and the small island. Nice work.', '2007-09-12 21:24:34.000000', NULL, 1),
(4085694, 585620, 81530, '<td valign="top">I like the simplicity of this photo. The interior provides a nice frame for the outside world. The silhouette of the person definitely adds to this photo.</td>', 'I like the simplicity of this photo. The interior provides a nice frame for the outside world. The silhouette of the person definitely adds to this photo.', '2007-09-12 21:25:30.000000', NULL, 1),
(4085696, 585651, 81530, '<td valign="top">Beautiful lighting throughout this photograph. I love the highlights of the blinds on the curtain and how they are diffused on the dresser. Very strong shot.</td>', 'Beautiful lighting throughout this photograph. I love the highlights of the blinds on the curtain and how they are diffused on the dresser. Very strong shot.', '2007-09-12 21:26:21.000000', NULL, 1),
(4085703, 584998, 81530, '<td valign="top">I really like what you have done here. The blurriness of the gate closing is what makes this shot interesting. You have really captured the "feeling" of closing. Well done.</td>', 'I really like what you have done here. The blurriness of the gate closing is what makes this shot interesting. You have really captured the "feeling" of closing. Well done.', '2007-09-12 21:30:07.000000', NULL, 1),
(4085706, 585503, 81530, '<td valign="top">Great sunset and silhouettes. The flying birds are a nice added touch.</td>', 'Great sunset and silhouettes. The flying birds are a nice added touch.', '2007-09-12 21:31:04.000000', NULL, 1),
(4085709, 585074, 81530, '<td valign="top">Great idea. It is a little subtle, and might be missed by some, but very creative.</td>', 'Great idea. It is a little subtle, and might be missed by some, but very creative.', '2007-09-12 21:33:10.000000', NULL, 1),
(4085711, 585011, 81530, '<td valign="top">Very strong photograph showing something closing. This is very strong in a technical sense as well as following the challenge topic. I expect to see this in the top 3. Great shot!</td>', 'Very strong photograph showing something closing. This is very strong in a technical sense as well as following the challenge topic. I expect to see this in the top 3. Great shot!', '2007-09-12 21:34:19.000000', NULL, 1),
(4085717, 584001, 81530, '<td valign="top">There is a lot of information to absorb with this photograph. I would be interested in seeing a closer crop that includes the main sign on the door and the man from the knees up.</td>', 'There is a lot of information to absorb with this photograph. I would be interested in seeing a closer crop that includes the main sign on the door and the man from the knees up.', '2007-09-12 21:36:44.000000', NULL, 1),
(4085718, 585228, 81530, '<td valign="top">Interesting lighting and shadows. This photo could benefit from a stronger focal point.</td>', 'Interesting lighting and shadows. This photo could benefit from a stronger focal point.', '2007-09-12 21:37:07.000000', NULL, 1),
(4085719, 584879, 81530, '<td valign="top">Very nice lighting and focus. I like the negative space you have left at the top, it gives the viewer a breather. Good luck!</td>', 'Very nice lighting and focus. I like the negative space you have left at the top, it gives the viewer a breather. Good luck!', '2007-09-12 21:37:54.000000', NULL, 1),
(4085722, 585628, 77196, '<td valign="top">Not sure how this meets the challenge. OOF, not sure what the grey/blue rash is from left center across the wood &amp; opening.</td>', 'Not sure how this meets the challenge. OOF, not sure what the grey/blue rash is from left center across the wood & opening.', '2007-09-12 21:38:07.000000', NULL, 1),
(4085725, 585422, 81530, '<td valign="top">Very nice lighting and colors on the flowers. The crop might be a little awkward. If possible, a wider crop might make this photograph stronger.</td>', 'Very nice lighting and colors on the flowers. The crop might be a little awkward. If possible, a wider crop might make this photograph stronger.', '2007-09-12 21:38:56.000000', NULL, 1),
(4085727, 584503, 81530, '<td valign="top">Very nice silhouette and colors in the sky. I like the sense of scale the boat provides.</td>', 'Very nice silhouette and colors in the sky. I like the sense of scale the boat provides.', '2007-09-12 21:40:11.000000', NULL, 1),
(4085729, 585688, 81530, '<td valign="top">Beautiful focus on the eyelashes and skin.</td>', 'Beautiful focus on the eyelashes and skin.', '2007-09-12 21:41:01.000000', NULL, 1),
(4085731, 585563, 77196, '<td valign="top">Extra point for creativity. Without the moving door, the picture is rather bland.</td>', 'Extra point for creativity. Without the moving door, the picture is rather bland.', '2007-09-12 21:42:21.000000', NULL, 1),
(4085734, 585732, 77196, '<td valign="top">Aligned seagulls are very distracting - can only tell what they are from their shadows. Nice color, and texture on the water.</td>', 'Aligned seagulls are very distracting - can only tell what they are from their shadows. Nice color, and texture on the water.', '2007-09-12 21:43:37.000000', NULL, 1),
(4085735, 585735, 81530, '<td valign="top">Very nice details in the sky. My eye keeps being drawn to the blue line at the bottom left corner, when I think the focus should be on the details in the sky. A different crop, or photoshop edit (after the challenge) could make this a little stronger. Nice shot.</td>', 'Very nice details in the sky. My eye keeps being drawn to the blue line at the bottom left corner, when I think the focus should be on the details in the sky. A different crop, or photoshop edit (after the challenge) could make this a little stronger. Nice shot.', '2007-09-12 21:44:02.000000', NULL, 1),
(4085736, 584991, 77196, '<td valign="top">Looks like the closing was some time ago...</td>', 'Looks like the closing was some time ago...', '2007-09-12 21:44:25.000000', NULL, 1),
(4085741, 585584, 81530, '<td valign="top">I like the details in the sky and on the road. The idea of closing is not as evident as it could be.</td>', 'I like the details in the sky and on the road. The idea of closing is not as evident as it could be.', '2007-09-12 21:46:24.000000', NULL, 1),
(4085750, 585737, 81530, '<td valign="top">Ooops. Hope you didn''t make too much of a mess. Where does the pizza go? I would be interested in seeing if a slower shutter speed would make the falling of the cup a little more dynamic.</td>', 'Ooops. Hope you didn''t make too much of a mess. Where does the pizza go? I would be interested in seeing if a slower shutter speed would make the falling of the cup a little more dynamic.', '2007-09-12 21:49:24.000000', NULL, 1),
(4085751, 585110, 81530, '<td valign="top">Very nice idea. I like that you have captured the act of closing. Good composition, lighting, and I like the dark background. Great shot.</td>', 'Very nice idea. I like that you have captured the act of closing. Good composition, lighting, and I like the dark background. Great shot.', '2007-09-12 21:49:54.000000', NULL, 1),
(4085755, 584988, 81530, '<td valign="top">Good contrast overall. I like the strong lines on the floor.</td>', 'Good contrast overall. I like the strong lines on the floor.', '2007-09-12 21:51:39.000000', NULL, 1),
(4085758, 585330, 81530, '<td valign="top">I love the colors in the sky as well as the fact all the details across the water seem relatively sharp. Very well done!</td>', 'I love the colors in the sky as well as the fact all the details across the water seem relatively sharp. Very well done!', '2007-09-12 21:52:21.000000', NULL, 1),
(4085762, 585803, 81530, '<td valign="top">Very comical. Great lighting. Normally I would say the crop is too tight, but it fits the subject matter of the photo. Well done.</td>', 'Very comical. Great lighting. Normally I would say the crop is too tight, but it fits the subject matter of the photo. Well done.', '2007-09-12 21:53:05.000000', NULL, 1),
(4085764, 585620, 77196, '<td valign="top">The bottom of the right shade is aligned too closely with the top of the building. It was not obvious to me at first that the grey under the shade was sky.</td>', 'The bottom of the right shade is aligned too closely with the top of the building. It was not obvious to me at first that the grey under the shade was sky.', '2007-09-12 21:53:29.000000', NULL, 1),
(4085765, 585656, 81530, '<td valign="top">Very nice focusing. I like the negative space in the background. It creates a nice balance.</td>', 'Very nice focusing. I like the negative space in the background. It creates a nice balance.', '2007-09-12 21:53:52.000000', NULL, 1),
(4085767, 583540, 81530, '<td valign="top">Mabuhay! Very nice sunset and contrast in the photo. I like the overall cool tone.</td>', 'Mabuhay! Very nice sunset and contrast in the photo. I like the overall cool tone.', '2007-09-12 21:54:55.000000', NULL, 1),
(4085770, 585690, 81530, '<td valign="top">Very nice details. You can see each individual hair. Great focus. Great shot overall.</td>', 'Very nice details. You can see each individual hair. Great focus. Great shot overall.', '2007-09-12 21:55:32.000000', NULL, 1),
(4085771, 585481, 81530, '<td valign="top">Nice action shot. The blurred wings give a sense of motion.</td>', 'Nice action shot. The blurred wings give a sense of motion.', '2007-09-12 21:55:48.000000', NULL, 1),
(4085772, 584622, 81530, '<td valign="top">Very nice highlights on the clouds. I like the details in the silhouettes as well.</td>', 'Very nice highlights on the clouds. I like the details in the silhouettes as well.', '2007-09-12 21:56:18.000000', NULL, 1),
(4085774, 585576, 81530, '<td valign="top">Nice subtle details. I like the contrast of the light flower and dark background.</td>', 'Nice subtle details. I like the contrast of the light flower and dark background.', '2007-09-12 21:56:39.000000', NULL, 1),
(4085780, 584462, 81530, '<td valign="top">Interesting idea. I think this photo would be stronger if it included a texture of a building as opposed to the sky since they two elements would relate more.</td>', 'Interesting idea. I think this photo would be stronger if it included a texture of a building as opposed to the sky since they two elements would relate more.', '2007-09-12 21:58:03.000000', NULL, 1),
(4085784, 585563, 84114, '<td valign="top">Great use of long exposure!</td>', 'Great use of long exposure!', '2007-09-12 21:59:12.000000', NULL, 1),
(4085791, 585426, 81530, '<td valign="top">Very nice sunset. I think this would be stronger as a vertical crop because you would focus more on the people and their actions. Right now the long horizontal lines pull your attention to the edges of the photo.</td>', 'Very nice sunset. I think this would be stronger as a vertical crop because you would focus more on the people and their actions. Right now the long horizontal lines pull your attention to the edges of the photo.', '2007-09-12 22:00:19.000000', NULL, 1),
(4085794, 585729, 81530, '<td valign="top">Nice sense of movement with the slow shutter speed.</td>', 'Nice sense of movement with the slow shutter speed.', '2007-09-12 22:00:41.000000', NULL, 1),
(4085795, 582979, 84114, '<td valign="top">That''s hilarious!</td>', 'That''s hilarious!', '2007-09-12 22:01:03.000000', NULL, 1),
(4085796, 585145, 84114, '<td valign="top">Wow. Hope they protect the tires!</td>', 'Wow. Hope they protect the tires!', '2007-09-12 22:01:31.000000', NULL, 1),
(4085803, 585228, 84114, '<td valign="top">Would be nice to see even just the bottom 1/3 as a silhouetted landscape to be able to offset the massive amount of purple. Beautiful, though!</td>', 'Would be nice to see even just the bottom 1/3 as a silhouetted landscape to be able to offset the massive amount of purple. Beautiful, though!', '2007-09-12 22:03:14.000000', NULL, 1),
(4085805, 585783, 81530, '<td valign="top">I might find this more interesting with the screwdriver resting on the computer as opposed to being in use. At this point, screwing that specific screw becomes the focal point, when I think the computer has more than one problem.</td>', 'I might find this more interesting with the screwdriver resting on the computer as opposed to being in use. At this point, screwing that specific screw becomes the focal point, when I think the computer has more than one problem.', '2007-09-12 22:03:44.000000', NULL, 1),
(4085807, 585563, 81530, '<td valign="top">Very nice idea for closing. I find the elements in the background a little distracting.</td>', 'Very nice idea for closing. I find the elements in the background a little distracting.', '2007-09-12 22:04:28.000000', NULL, 1),
(4085810, 585768, 84114, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2007-09-12 22:04:57.000000', NULL, 1),
(4085814, 585033, 81530, '<td valign="top">I like the repetition the bars create and the break provided by the lock. Great lighting, great contrast, great composition, great photo.</td>', 'I like the repetition the bars create and the break provided by the lock. Great lighting, great contrast, great composition, great photo.', '2007-09-12 22:05:23.000000', NULL, 1),
(4085815, 585011, 65811, '<td valign="top">Cool action shot, nicely done.</td>', 'Cool action shot, nicely done.', '2007-09-12 22:05:44.000000', NULL, 1),
(4085818, 585071, 84114, '<td valign="top">Answer: Very Carefully.</td>', 'Answer: Very Carefully.', '2007-09-12 22:05:57.000000', NULL, 1),
(4085822, 584615, 84114, '<td valign="top">Not sure if the spider is out of focus or overexposed. Nice composition, though.</td>', 'Not sure if the spider is out of focus or overexposed. Nice composition, though.', '2007-09-12 22:06:38.000000', NULL, 1),
(4085825, 585362, 84114, '<td valign="top">A very solemn picture.</td>', 'A very solemn picture.', '2007-09-12 22:07:29.000000', NULL, 1),
(4085826, 583991, 65811, '<td valign="top">Great shot, I love the detail.  Must have been quite a stretch to get this!</td>', 'Great shot, I love the detail.  Must have been quite a stretch to get this!', '2007-09-12 22:07:29.000000', NULL, 1),
(4085829, 583958, 81530, '<td valign="top">Nice details on the cactus/flower. I like the blurred background. I think there is too much negative space at the top that distracts from the details of the plant.</td>', 'Nice details on the cactus/flower. I like the blurred background. I think there is too much negative space at the top that distracts from the details of the plant.', '2007-09-12 22:08:08.000000', NULL, 1),
(4085832, 585011, 84114, '<td valign="top">Very nice use of a long exposure! I''ll have to remember that trick.</td>', 'Very nice use of a long exposure! I''ll have to remember that trick.', '2007-09-12 22:08:35.000000', NULL, 1),
(4085835, 582979, 81530, '<td valign="top">Nice idea. The crop is a little tight overall. A little more negative space around the edges could help.</td>', 'Nice idea. The crop is a little tight overall. A little more negative space around the edges could help.', '2007-09-12 22:09:13.000000', NULL, 1),
(4085838, 585110, 84114, '<td valign="top">Nice execution, but the photo seems... empty. I wonder how it would look with a white background?</td>', 'Nice execution, but the photo seems... empty. I wonder how it would look with a white background?', '2007-09-12 22:09:49.000000', NULL, 1),
(4085839, 584615, 65811, '<td valign="top">The focus is just a little too soft for me.  Great capture though.</td>', 'The focus is just a little too soft for me.  Great capture though.', '2007-09-12 22:10:09.000000', NULL, 1),
(4085841, 584991, 84114, '<td valign="top">Lovely sepia tones.</td>', 'Lovely sepia tones.', '2007-09-12 22:10:33.000000', NULL, 1),
(4085846, 585218, 84114, '<td valign="top">Nice silhouette.</td>', 'Nice silhouette.', '2007-09-12 22:11:24.000000', NULL, 1),
(4085848, 585781, 65811, '<td valign="top">Lucky to find this!  Nice capture, I like the sheen of the web.</td>', 'Lucky to find this!  Nice capture, I like the sheen of the web.', '2007-09-12 22:11:59.000000', NULL, 1),
(4085849, 585628, 81530, '<td valign="top">This appears to be shot through glass, or is a photo of a print. The composition is interesting, but it could benefit from a better focus and more contrast overall.</td>', 'This appears to be shot through glass, or is a photo of a print. The composition is interesting, but it could benefit from a better focus and more contrast overall.', '2007-09-12 22:12:07.000000', NULL, 1),
(4085854, 585817, 81530, '<td valign="top">Poor kid! That can''t be comfortable. Very night lighting. The crop is a little awkward.</td>', 'Poor kid! That can''t be comfortable. Very night lighting. The crop is a little awkward.', '2007-09-12 22:13:37.000000', NULL, 1),
(4085857, 585759, 81530, '<td valign="top">Very strong focusing on the leaf. I like the patterns created in the water. Very well done.</td>', 'Very strong focusing on the leaf. I like the patterns created in the water. Very well done.', '2007-09-12 22:14:03.000000', NULL, 1),
(4085861, 585735, 84114, '<td valign="top">Great shot, but it may be nicer to see the horizon 1/3 of the way up the frame. See <a href="//en.wikipedia.org/wiki/Rule_of_thirds" rel="nofollow" target="_blank">Rule of Thirds (Wikipedia)</a></td>', 'Great shot, but it may be nicer to see the horizon 1/3 of the way up the frame. See Rule of Thirds (Wikipedia)', '2007-09-12 22:15:35.000000', NULL, 1),
(4085864, 585717, 81530, '<td valign="top">Very nice lighting. I like the contrast of the bright light on the door, and the dark walls inside. I like that the little girl is anonymous. I also like that she is wearing a similar color because it relates the two main subject. The one thing I would change is the color of her shoes, they are very distracting. Changing them to red could make this photo sing in harmony.</td>', 'Very nice lighting. I like the contrast of the bright light on the door, and the dark walls inside. I like that the little girl is anonymous. I also like that she is wearing a similar color because it relates the two main subject. The one thing I would change is the color of her shoes, they are very distracting. Changing them to red could make this photo sing in harmony.', '2007-09-12 22:15:53.000000', NULL, 1),
(4085866, 583656, 81530, '<td valign="top">Very nice focus, and subtle color.</td>', 'Very nice focus, and subtle color.', '2007-09-12 22:16:16.000000', NULL, 1),
(4085867, 585620, 84114, '<td valign="top">Wow. Nice composition and use of the Rule of Thirds.</td>', 'Wow. Nice composition and use of the Rule of Thirds.', '2007-09-12 22:16:26.000000', NULL, 1),
(4085869, 583891, 65811, '<td valign="top">Hmm, very creative.  Great lighting.  Don''t think I want to know how you did this though :P.</td>', 'Hmm, very creative.  Great lighting.  Don''t think I want to know how you did this though :P.', '2007-09-12 22:16:29.000000', NULL, 1),
(4085871, 585440, 81530, '<td valign="top">With very nice lighting, contrast and color, you have turned a everyday shot into something special. Well done.</td>', 'With very nice lighting, contrast and color, you have turned a everyday shot into something special. Well done.', '2007-09-12 22:16:53.000000', NULL, 1),
(4085874, 584310, 84114, '<td valign="top">Nice. Even more fun when trees do that to cable and power lines :)</td>', 'Nice. Even more fun when trees do that to cable and power lines :)', '2007-09-12 22:17:42.000000', NULL, 1),
(4085878, 583891, 81530, '<td valign="top">I hope that is a cardboard cutout..lol Very strong composition. Nice range of values. Great shot.</td>', 'I hope that is a cardboard cutout..lol Very strong composition. Nice range of values. Great shot.', '2007-09-12 22:17:57.000000', NULL, 1),
(4085883, 583415, 84114, '<td valign="top">No Trespassing! :)</td>', 'No Trespassing! :)', '2007-09-12 22:18:46.000000', NULL, 1),
(4085884, 584991, 81530, '<td valign="top">Nice idea. The highlights are a little bright. There is a lot of information to take in, perhaps a tighter crop would make this photo a little simpler.</td>', 'Nice idea. The highlights are a little bright. There is a lot of information to take in, perhaps a tighter crop would make this photo a little simpler.', '2007-09-12 22:18:49.000000', NULL, 1),
(4085887, 585299, 65811, '<td valign="top">Interesting idea, focus is soft in strange areas IMO.  I like the lighting.</td>', 'Interesting idea, focus is soft in strange areas IMO.  I like the lighting.', '2007-09-12 22:19:03.000000', NULL, 1),
(4085888, 585362, 81530, '<td valign="top">Very strong focus. The colors are very rich and look great against the monotone background.</td>', 'Very strong focus. The colors are very rich and look great against the monotone background.', '2007-09-12 22:19:24.000000', NULL, 1),
(4085889, 585817, 84114, '<td valign="top">Yikes. Is there a doctor in the house?</td>', 'Yikes. Is there a doctor in the house?', '2007-09-12 22:19:35.000000', NULL, 1),
(4085893, 585481, 84114, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2007-09-12 22:20:10.000000', NULL, 1),
(4085895, 585468, 81530, '<td valign="top">Very nice idea. I like the texture of the sand. I feel this photograph might be stronger with just the single blade of grass and its shadow.</td>', 'Very nice idea. I like the texture of the sand. I feel this photograph might be stronger with just the single blade of grass and its shadow.', '2007-09-12 22:20:21.000000', NULL, 1),
(4085896, 585741, 81530, '<td valign="top">Very nice focus and soft lighting.</td>', 'Very nice focus and soft lighting.', '2007-09-12 22:20:35.000000', NULL, 1),
(4085898, 584392, 81530, '<td valign="top">Very nice sunset and highlights in the clouds. Less dark foreground might make this photo stronger.</td>', 'Very nice sunset and highlights in the clouds. Less dark foreground might make this photo stronger.', '2007-09-12 22:21:06.000000', NULL, 1),
