(4085903, 585228, 65811, '<td valign="top">cool capture!</td>', 'cool capture!', '2007-09-12 22:22:14.000000', NULL, 1),
(4085904, 585330, 84114, '<td valign="top">Very nice.</td>', 'Very nice.', '2007-09-12 22:22:21.000000', NULL, 1),
(4085906, 585033, 65811, '<td valign="top">Very creative, great texture.</td>', 'Very creative, great texture.', '2007-09-12 22:22:45.000000', NULL, 1),
