INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4087430, 585575, 68035, '<td valign="top">Great title quote which complements the image entirely.  Nice technique</td>', 'Great title quote which complements the image entirely.  Nice technique', '2007-09-13 13:16:09.000000', NULL, 1),
(4087436, 585803, 68035, '<td valign="top">There is something distinctly uneasy about this image (other than the fact that someone is being squashed in a piece of gym equipment).  The subjects expression is almost bordering on the grotesque and perhaps it is this blend of humour and genuine horror which make me both like this shot and recoil from it at the same time.  Uneasily bumping it to 7</td>', 'There is something distinctly uneasy about this image (other than the fact that someone is being squashed in a piece of gym equipment).  The subjects expression is almost bordering on the grotesque and perhaps it is this blend of humour and genuine horror which make me both like this shot and recoil from it at the same time.  Uneasily bumping it to 7', '2007-09-13 13:18:43.000000', NULL, 1),
(4087439, 585480, 68035, '<td valign="top">A couple of people have gone for the yes open/shut idea in this challenge which may impact on your score but I do like this one.  The use of the hair to produce a half face portrait is excellent</td>', 'A couple of people have gone for the yes open/shut idea in this challenge which may impact on your score but I do like this one.  The use of the hair to produce a half face portrait is excellent', '2007-09-13 13:19:51.000000', NULL, 1),
(4087443, 585688, 68035, '<td valign="top">Lovely macro, not sure whether it fully conveys the idea of something in the act of closing to me (rather something that is already closed) but there is a lovely serenity to the subjects face which gives the image a strange beauty.  Certainly I wish I could take a shot like this<br/> <br/>Super conversion bumping to 7</td>', 'Lovely macro, not sure whether it fully conveys the idea of something in the act of closing to me (rather something that is already closed) but there is a lovely serenity to the subjects face which gives the image a strange beauty.  Certainly I wish I could take a shot like this Super conversion bumping to 7', '2007-09-13 13:22:02.000000', NULL, 1),
(4087552, 585196, 39825, '<td valign="top">scary!!!!!! but great. how did you do that?!</td>', 'scary!!!!!! but great. how did you do that?!', '2007-09-13 14:19:40.000000', NULL, 1),
(4087554, 585759, 26001, '<td valign="top">very delicately captured with nice colors. 8</td>', 'very delicately captured with nice colors. 8', '2007-09-13 14:22:37.000000', NULL, 1),
(4087555, 585584, 26001, '<td valign="top">excellent use of wide angle. crossing in the foreground, circular building, clouds in the sky, even the cyclist with motion blur, everything works very well together. taking of only 1 point for the blue-cast. 9</td>', 'excellent use of wide angle. crossing in the foreground, circular building, clouds in the sky, even the cyclist with motion blur, everything works very well together. taking of only 1 point for the blue-cast. 9', '2007-09-13 14:24:03.000000', NULL, 1),
(4087558, 583891, 26001, '<td valign="top">i like the concept a lot and giving you 8<br/>ps: i hope you setup a real card-board inside the toilet(not a mix of two exposures). otherwise it will be DQed under the basic editing.</td>', 'i like the concept a lot and giving you 8ps: i hope you setup a real card-board inside the toilet(not a mix of two exposures). otherwise it will be DQed under the basic editing.', '2007-09-13 14:26:01.000000', NULL, 1),
(4087560, 585781, 26001, '<td valign="top">excellent concept delicately captured. beautiful bokeh and dof work 8</td>', 'excellent concept delicately captured. beautiful bokeh and dof work 8', '2007-09-13 14:26:35.000000', NULL, 1),
(4087562, 585803, 26001, '<td valign="top">this is hysterical 8</td>', 'this is hysterical 8', '2007-09-13 14:27:20.000000', NULL, 1),
(4087568, 585480, 26001, '<td valign="top">creepy! i like it.<br/>i know it would have been difficult but wish there wasnt so much motion blur on the rest of the face/hair. still 7 for the concept</td>', 'creepy! i like it.i know it would have been difficult but wish there wasnt so much motion blur on the rest of the face/hair. still 7 for the concept', '2007-09-13 14:29:31.000000', NULL, 1),
