(4088459, 585330, 73564, '<td valign="top">This must have alot of views, it didn''t have to load, great picture, love the composition, colors are really nice, my first 10 of the challenge, hope to see this one make home page, good luck!</td>', 'This must have alot of views, it didn''t have to load, great picture, love the composition, colors are really nice, my first 10 of the challenge, hope to see this one make home page, good luck!', '2007-09-13 22:53:53.000000', NULL, 1),
(4088465, 585110, 73564, '<td valign="top">Absolutly love the composition on this image, maybe would have seen how this would have looked with out the spot below the watch, but this is great as is, nice work, my second 10.</td>', 'Absolutly love the composition on this image, maybe would have seen how this would have looked with out the spot below the watch, but this is great as is, nice work, my second 10.', '2007-09-13 22:56:54.000000', NULL, 1),
