(4088631, 585196, 62249, '<td valign="top">Creepy!</td>', 'Creepy!', '2007-09-14 00:13:36.000000', NULL, 1),
(4088972, 582979, 14437, '<td valign="top">A clean shot. Just that the object is less interesting. I would have preferred more room around both sign.</td>', 'A clean shot. Just that the object is less interesting. I would have preferred more room around both sign.', '2007-09-14 05:34:46.000000', NULL, 1),
(4088973, 583656, 14437, '<td valign="top">Basically I don''t get what you are trying to tell with this shot. Close macro? No feel of challenge.</td>', 'Basically I don''t get what you are trying to tell with this shot. Close macro? No feel of challenge.', '2007-09-14 05:35:54.000000', NULL, 1),
(4088974, 583668, 14437, '<td valign="top">The shot is blur. Perhaps you shall use a faster shutter speed. And what''s the hand doing in the frame. It spoils the shot.</td>', 'The shot is blur. Perhaps you shall use a faster shutter speed. And what''s the hand doing in the frame. It spoils the shot.', '2007-09-14 05:36:43.000000', NULL, 1),
(4088976, 584138, 14437, '<td valign="top">Sometimes you shall obey the rule of third. And the color is out, perhaps the white balance shall be manually set.</td>', 'Sometimes you shall obey the rule of third. And the color is out, perhaps the white balance shall be manually set.', '2007-09-14 05:38:08.000000', NULL, 1),
(4088978, 583540, 14437, '<td valign="top">Nice color. The composition is find. But the sea horizontal line is not horizontal. You should have rotate a little anti-clockwise during PP.</td>', 'Nice color. The composition is find. But the sea horizontal line is not horizontal. You should have rotate a little anti-clockwise during PP.', '2007-09-14 05:39:23.000000', NULL, 1),
(4088979, 585444, 14437, '<td valign="top">Nice leaf. But the back ground is too busy to my liking. Perhaps taking from a low angle showing a nice bokeh will improve the shot.</td>', 'Nice leaf. But the back ground is too busy to my liking. Perhaps taking from a low angle showing a nice bokeh will improve the shot.', '2007-09-14 05:40:14.000000', NULL, 1),
(4088980, 585480, 14437, '<td valign="top">Creative. But this could be executed better. The tone is dull and the image is blur.</td>', 'Creative. But this could be executed better. The tone is dull and the image is blur.', '2007-09-14 05:41:05.000000', NULL, 1),
(4088981, 584991, 14437, '<td valign="top">Barrel distortion is serious in this shot. And the composition could be much better.</td>', 'Barrel distortion is serious in this shot. And the composition could be much better.', '2007-09-14 05:41:55.000000', NULL, 1),
(4088982, 585737, 14437, '<td valign="top">Oh well... I still remember this joke :)<br/>The photo is grainy, and the subject is not stand out. Shooting indoor needs a dramatic lighting to make it standout. Some tungsten lights might help, rather than those fluorescent white light.</td>', 'Oh well... I still remember this joke :)The photo is grainy, and the subject is not stand out. Shooting indoor needs a dramatic lighting to make it standout. Some tungsten lights might help, rather than those fluorescent white light.', '2007-09-14 05:44:14.000000', NULL, 1),
(4088983, 583974, 14437, '<td valign="top">Other than the half filled drink, I don''t feel the challenge.</td>', 'Other than the half filled drink, I don''t feel the challenge.', '2007-09-14 05:45:01.000000', NULL, 1),
(4088984, 583991, 14437, '<td valign="top">I like the tight composition. And the detail is great. However I would have preferred some S-curve adjustment to make the color pop out more.</td>', 'I like the tight composition. And the detail is great. However I would have preferred some S-curve adjustment to make the color pop out more.', '2007-09-14 05:45:57.000000', NULL, 1),
(4088986, 585620, 14437, '<td valign="top">It''s risky composing a shot like this. Because it can''t really tell if she''s is opening or closing the blind. And the barrel distortion is serious.</td>', 'It''s risky composing a shot like this. Because it can''t really tell if she''s is opening or closing the blind. And the barrel distortion is serious.', '2007-09-14 05:47:06.000000', NULL, 1),
(4088987, 583891, 14437, '<td valign="top">Very creative :) Why not in color?</td>', 'Very creative :) Why not in color?', '2007-09-14 05:47:43.000000', NULL, 1),
