(4088989, 585330, 14437, '<td valign="top">I like the color tone.</td>', 'I like the color tone.', '2007-09-14 05:49:07.000000', NULL, 1),
(4088990, 585576, 14437, '<td valign="top">I can''t really tell from the shot that it''s end of life... the message needs to be brought out from the shot, not just from the title.</td>', 'I can''t really tell from the shot that it''s end of life... the message needs to be brought out from the shot, not just from the title.', '2007-09-14 05:50:07.000000', NULL, 1),
