(4088997, 584863, 14437, '<td valign="top">It''s risky to have such composition because the shot failed to convey the message of closing.</td>', 'It''s risky to have such composition because the shot failed to convey the message of closing.', '2007-09-14 05:56:51.000000', NULL, 1),
