(4101159, 585735, 68642, '<td valign="top">ALRIGHT !!!!!  MY FIRST TOP TEN PHOTO!  whhhhheeeeeeeeeeeeee<br/> <br/>Thanks everyone for the votes and comments.</td>', 'ALRIGHT !!!!!  MY FIRST TOP TEN PHOTO!  whhhhheeeeeeeeeeeeee Thanks everyone for the votes and comments.', '2007-09-19 09:00:03.000000', NULL, 0),
(4101164, 585781, 66597, '<td valign="top">Colleen - congrats on your HM! Cool shot, love the colors.</td>', 'Colleen - congrats on your HM! Cool shot, love the colors.', '2007-09-19 09:02:51.000000', NULL, 0),
(4101224, 585781, 23484, '<td valign="top">Nice job Collen. Great clutter free background. Congrats on the 4th place.</td>', 'Nice job Collen. Great clutter free background. Congrats on the 4th place.', '2007-09-19 09:27:41.000000', NULL, 0),
(4101232, 585480, 83391, '<td valign="top">Thanks for all the compliments and the criticisms.  I know it was slightly blurry.  I was going to shoot this one of her lying down instead but didn''t think the hair would fall the way I wanted to.  I even used a tripod and a cord so it must have been her moving.<br/> <br/>I did like the effect I captured though and only had a couple hours before the posting deadline by the time I got the images off the camera.  I may do this one again and make it better just as an experiment.  My first challenge and I plan on making the next one a little better.<br/> <br/>Again, thanks for the nice comments, I thought it was creepy too!</td>', 'Thanks for all the compliments and the criticisms.  I know it was slightly blurry.  I was going to shoot this one of her lying down instead but didn''t think the hair would fall the way I wanted to.  I even used a tripod and a cord so it must have been her moving. I did like the effect I captured though and only had a couple hours before the posting deadline by the time I got the images off the camera.  I may do this one again and make it better just as an experiment.  My first challenge and I plan on making the next one a little better. Again, thanks for the nice comments, I thought it was creepy too!', '2007-09-19 09:30:42.000000', NULL, 0),
(4101238, 585781, 41047, '<td valign="top">wow, congrats on top 5 colleen! i love the idea and the title, great capture.</td>', 'wow, congrats on top 5 colleen! i love the idea and the title, great capture.', '2007-09-19 09:32:16.000000', NULL, 0),
(4101303, 585781, 61651, '<td valign="top">Loving that new macro, huh?  Beautifully shot and great, subtle idea for the challenge theme.  Congrats on 4th!</td>', 'Loving that new macro, huh?  Beautifully shot and great, subtle idea for the challenge theme.  Congrats on 4th!', '2007-09-19 09:58:06.000000', NULL, 0),
